mapper.select:
SELECT a.id, a.title, a.summary, a.cover_img, a.is_top, a.view_count, a.comment_count, a.create_time, a.category_id, c.name AS category_name FROM blog_article a LEFT JOIN blog_category c ON a.category_id = c.id
a.deleted = 0
AND a.status = #{status}
AND a.category_id = #{categoryId}
AND EXISTS ( SELECT 1 FROM blog_article_tag at WHERE at.article_id = a.id AND at.tag_id = #{tagId} )
AND (a.title LIKE CONCAT('%', #{keyword}, '%') OR a.summary LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY a.is_top DESC, a.create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM blog_article a

    a.deleted = 0

        AND a.status = #{status}


        AND a.category_id = #{categoryId}


        AND EXISTS (
            SELECT 1 FROM blog_article_tag at
            WHERE at.article_id = a.id AND at.tag_id = #{tagId}
        )


        AND (a.title LIKE CONCAT('%', #{keyword}, '%')
             OR a.summary LIKE CONCAT('%', #{keyword}, '%'))
